<?php
declare(strict_types=1);
require_once __DIR__.'/app/bootstrap.php';
$page=max(1,(int)($_GET['page']??1)); $per=10;
$total=(int)$pdo->query("SELECT COUNT(*) FROM notices WHERE status='published'")->fetchColumn();
$pages=max(1,(int)ceil($total/$per)); if($page>$pages){$page=$pages;}
$stmt=$pdo->prepare("SELECT id,title,notice_date FROM notices WHERE status='published' ORDER BY notice_date DESC,id DESC LIMIT :lim OFFSET :off");
$stmt->bindValue(':lim',$per,PDO::PARAM_INT);$stmt->bindValue(':off',($page-1)*$per,PDO::PARAM_INT);$stmt->execute();$rows=$stmt->fetchAll();
